content.text:
*{
box-sizing:border-box}
 :root{
--ink:#f3eee6;--muted:#a19b92;--gold:#d8b889;--panel:#17181b;--line:rgba(255,255,255,.085);--bg:#101114}
html,body{
margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:'DM Sans',sans-serif}
button{
font:inherit;color:inherit;cursor:pointer}
.app-shell{
height:100dvh;min-height:640px;display:flex;flex-direction:column;max-width:1800px;margin:auto;padding:0 36px;background:radial-gradient(ellipse at 48% 45%,#202125 0,#151619 38%,#101114 75%)}
.topbar{
height:72px;flex-shrink:0;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}
.brand{
display:flex;align-items:center;gap:10px;text-decoration:none;color:#f5eee4;font-family:'Playfair Display',serif;font-size:21px;letter-spacing:-.4px}
.brand-mark{
display:grid;place-items:center;width:29px;height:29px;border:1px solid rgba(216,184,137,.64);border-radius:50%;color:var(--gold);font-size:21px;font-style:italic;line-height:1}
.brand-light{
color:#aaa39b;font-weight:500}
.session-pill{
font-size:9px;letter-spacing:1.75px;color:#8f8a83;display:flex;align-items:center;gap:9px}
.session-pill b{
font-weight:500;color:#d7c9b4;margin-left:4px}
.live-dot{
height:6px;width:6px;border-radius:50%;background:#c9a779;box-shadow:0 0 9px #c9a779}
.quiet-btn{
border:0;background:transparent;color:#aaa49d;display:flex;align-items:center;gap:8px;font-size:11px;padding:8px 0}
.quiet-btn:hover{
color:white}
.reset-icon{
font-size:18px;color:#c5b194}
.workspace{
flex:1;min-height:0;display:grid;grid-template-columns:230px minmax(480px,1fr) 245px;gap:28px;padding:27px 0 21px}
.left-rail,.tool-panel{
min-height:0;display:flex;flex-direction:column}
.rail-heading,.tools-header,.view-heading{
display:flex;justify-content:space-between;align-items:center}
.eyebrow{
font-size:9px;letter-spacing:1.8px;font-weight:600;color:#aaa39a}
.step-count{
font-size:10px;color:#ded6ca}
.step-count i{
font-style:normal;color:#6d6a66}
.look-card{
margin-top:14px;padding:13px 15px 15px;background:linear-gradient(145deg,#222326,#1a1b1e);border:1px solid rgba(255,255,255,.055);border-radius:8px}
.look-swatch{
height:116px;position:relative;overflow:hidden;border-radius:4px;background:radial-gradient(ellipse at 55% 25%,#8d6a4e 0,#503d32 33%,#302923 75%)}
.look-swatch:before{
content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(244,205,158,.18),transparent 42%,rgba(0,0,0,.4))}
.swatch-hair{
position:absolute;width:74px;height:108px;left:calc(50% - 35px);top:13px;border-radius:49% 49% 42% 42%/38% 38% 58% 58%;background:repeating-linear-gradient(94deg,#1d1714 0,#33231b 3px,#583a28 6px,#281d18 9px,#191515 12px);box-shadow:5px 8px 13px #18120e}
.swatch-hair:after{
content:'';position:absolute;left:2px;right:2px;bottom:-3px;height:42px;border-radius:0 0 40% 40%;background:repeating-linear-gradient(96deg,#201714 0,#533823 5px,#211916 8px)}
.sparkle{
position:absolute;right:13px;top:10px;color:#ebd1ac;font-size:14px}
.look-title{
font:600 19px 'Playfair Display',serif;margin-top:14px;color:#f3e8dc}
.look-subtitle{
font-size:10px;color:#9c958c;margin-top:5px}
.look-rule{
height:1px;background:var(--line);margin:16px 0 12px}
.goal-row{
display:flex;justify-content:space-between;font-size:10px;color:#b1aba2}
.goal-row strong{
font-size:10px;color:#e3cda9;font-weight:500}
.goal-meter{
height:3px;background:#373638;border-radius:5px;margin:10px 0 7px;overflow:hidden}
.goal-meter i{
display:block;width:0;height:100%;background:linear-gradient(90deg,#a87851,#e9c89b);border-radius:4px;transition:width .5s}
.goal-caption{
display:flex;justify-content:space-between;font-size:8px;color:#817b75}
.goal-caption span:last-child{
color:#c8ab84}
.coach-note{
margin-top:16px;display:flex;gap:10px;padding:12px 12px;border:1px solid rgba(215,182,137,.13);background:rgba(190,153,106,.045);border-radius:6px}
.note-icon{
font-size:16px;color:#d8b889}
.coach-note b{
font-size:10px;color:#dac6a8;font-weight:600}
.coach-note p{
font-size:9px;line-height:1.55;color:#a49c92;margin:5px 0 0}
.quality-card{
margin-top:17px;padding-top:13px;border-top:1px solid var(--line)}
.quality-top{
display:flex;justify-content:space-between;color:#99938b;font-size:8px;letter-spacing:1.2px}
.quality-top span:last-child{
color:#d8bc95;letter-spacing:0;font-size:10px}
.quality-bars{
display:flex;gap:4px;margin:10px 0 7px}
.quality-bars i{
height:3px;background:#38383a;flex:1;border-radius:3px}
.quality-bars i.lit{
background:#d3ad7d}
.quality-card p{
margin:0;color:#7e7b77;font-size:9px}
.rail-foot{
margin-top:auto;color:#77736e;font:italic 10px 'Playfair Display',serif;display:flex;gap:8px;align-items:center}
.tiny-star{
color:#c8a980;font-style:normal}
.stage-column{
display:flex;min-width:0;flex-direction:column}
.stage-topline{
display:flex;justify-content:space-between;align-items:center;height:32px;flex-shrink:0}
.stage-topline>div:first-child{
display:flex;gap:13px;align-items:center}
.stage-sub{
font-size:9px;color:#777772}
.keycap{
border:1px solid #444247;border-radius:3px;padding:1px 5px;margin-left:4px;color:#aaa}
.scene-status{
font-size:8px;letter-spacing:1px;color:#aaa39a;display:flex;align-items:center;gap:7px}
.scene-status .live-dot{
height:5px;width:5px}
.stage{
position:relative;flex:1;min-height:320px;overflow:hidden;background:radial-gradient(ellipse at 51% 42%,#353338 0,#29282b 27%,#222124 58%,#19191c 100%);border:1px solid rgba(255,255,255,.07);border-radius:7px;box-shadow:0 18px 55px rgba(0,0,0,.26),inset 0 0 70px rgba(0,0,0,.18);touch-action:none}
.stage:before{
content:'';position:absolute;z-index:0;left:8%;right:8%;bottom:8%;height:18%;border-radius:50%;background:radial-gradient(ellipse,rgba(205,166,124,.12),rgba(176,143,113,.025) 45%,transparent 72%);filter:blur(13px)}
#scene{
position:absolute;inset:0;width:100%;height:100%;z-index:1;touch-action:none;cursor:none;outline:none}
.stage-vignette{
position:absolute;inset:0;z-index:2;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,rgba(11,11,13,.27) 100%)}
.headset-badge,.wind-status{
position:absolute;z-index:3;top:16px;font-size:8px;letter-spacing:1.15px;color:#b9b1a6;background:rgba(17,17,19,.45);border:1px solid rgba(255,255,255,.095);padding:8px 10px;border-radius:4px;backdrop-filter:blur(8px)}
.headset-badge{
left:16px}
.headset-badge span{
color:#d9bd97;margin-right:5px}
.wind-status{
right:16px;display:flex;align-items:center;gap:6px;color:#d9c4a4}
.wind-glyph{
font-size:14px;color:#e2c89f}
.stage-bottom-left,.stage-bottom-right{
position:absolute;z-index:3;bottom:15px}
.stage-bottom-left{
left:16px}
.mouse-hint{
font-size:9px;color:#b0aaa3;padding:8px 10px;border-radius:4px;background:rgba(14,14,16,.47);border:1px solid rgba(255,255,255,.08)}
.mouse-hint i{
font-style:normal;color:#e1c59f;margin-right:6px;font-size:13px}
.stage-bottom-right{
right:15px}
.wind-btn{
border:1px solid rgba(255,255,255,.12);background:rgba(20,20,22,.55);border-radius:4px;padding:7px 9px;display:flex;align-items:center;gap:7px;font-size:9px;color:#c8c0b5;backdrop-filter:blur(6px)}
.wind-btn>span:first-child{
color:#dfc39a;font-size:14px}
.wind-btn b{
font-size:7px;letter-spacing:.8px;color:#d3ad7d;margin-left:3px}
.cursor-tool{
position:absolute;z-index:5;pointer-events:none;width:53px;height:53px;display:none;transform:translate(-9px,-28px);filter:drop-shadow(0 3px 4px rgba(0,0,0,.5));transition:opacity .15s}
.cursor-tool svg{
width:100%;height:100%;fill:none;stroke:#ead3b2;stroke-width:2.1;stroke-linecap:round;stroke-linejoin:round}
.cursor-tool.comb-cursor svg{
stroke:#d9bd97}
.stage.cutting{
cursor:none}
.cut-flash{
position:absolute;z-index:7;left:50%;top:43%;transform:translate(-50%,-50%) scale(.8);opacity:0;pointer-events:none;background:rgba(25,21,19,.82);border:1px solid rgba(222,186,142,.3);color:#e5c59d;border-radius:30px;padding:9px 16px;font:12px 'Playfair Display',serif;transition:.24s}
.cut-flash.show{
opacity:1;transform:translate(-50%,-50%) scale(1)}
.cut-flash span{
color:#f3e4d1;margin-left:5px}
.toast{
position:absolute;z-index:8;left:50%;top:17%;transform:translate(-50%,-7px);opacity:0;pointer-events:none;background:#d8b889;color:#211a15;padding:8px 13px;border-radius:4px;font-size:10px;transition:.2s}
.toast.show{
opacity:1;transform:translate(-50%,0)}
.stage-footer{
height:68px;display:flex;align-items:center;justify-content:space-between;gap:15px;flex-shrink:0}
.client-info{
display:flex;align-items:center;gap:10px;min-width:156px}
.avatar{
height:32px;width:32px;display:grid;place-items:center;border:1px solid #6f5c4d;border-radius:50%;background:linear-gradient(135deg,#827060,#3e3430);font:15px 'Playfair Display',serif;color:#f2dec2}
.client-info b{
display:block;font:600 11px 'Playfair Display',serif;color:#e8dfd3}
.client-info span{
display:block;margin-top:3px;font-size:8px;color:#89837c}
.client-info span i{
font-style:normal;color:#c4a77e}
.footer-tip{
font-size:9px;color:#918a81;display:flex;align-items:center;gap:7px;white-space:nowrap}
.footer-tip>span:first-child{
color:#d0ad81}
.finish-btn{
border:1px solid #c7a77d;background:linear-gradient(110deg,#c5a176,#dcc39f);color:#221c16;border-radius:4px;padding:10px 13px;font-size:9px;font-weight:700;white-space:nowrap;box-shadow:0 4px 14px #0003}
.finish-btn:hover{
filter:brightness(1.09)}
.finish-btn span{
font-size:13px;margin-left:8px}
.tool-panel{
padding-top:2px}
.tool-count{
font-size:8px;letter-spacing:1px;color:#756f68}
.tool-list{
display:flex;flex-direction:column;gap:7px;margin-top:14px}
.tool-card{
position:relative;width:100%;height:58px;display:flex;align-items:center;text-align:left;border-radius:5px;border:1px solid rgba(255,255,255,.055);background:rgba(255,255,255,.022);padding:7px 9px;gap:10px;transition:.18s}
.tool-card:hover{
background:rgba(255,255,255,.055);border-color:#5b5146}
.tool-card.selected{
background:linear-gradient(100deg,rgba(196,158,112,.14),rgba(196,158,112,.04));border-color:rgba(209,174,132,.44);box-shadow:inset 2px 0 #d7b58b}
.tool-icon{
width:37px;height:37px;border:1px solid rgba(255,255,255,.075);background:rgba(0,0,0,.15);border-radius:4px;display:grid;place-items:center;flex-shrink:0}
.tool-icon svg{
width:28px;height:28px;fill:none;stroke:#d1b894;stroke-width:1.45;stroke-linecap:round;stroke-linejoin:round}
.thinning-icon svg{
stroke:#b8a48b}
.clipper-icon svg{
stroke:#beb7ad}
.comb-icon svg{
stroke:#c4aa84}
.tool-copy{
display:flex;flex-direction:column;gap:4px;min-width:0}
.tool-copy b{
font-size:10px;font-weight:600;color:#e4ddd4;white-space:nowrap}
.tool-copy small{
font-size:8px;color:#8b857e}
.tool-key{
align-self:flex-start;margin-left:auto;border:1px solid rgba(255,255,255,.1);border-radius:3px;color:#817b73;font-size:8px;padding:2px 5px}
.tool-hint{
display:flex;gap:9px;margin:12px 2px 16px;color:#969087;font-size:9px;line-height:1.5}
.hint-spark{
color:#d9bb91;font-size:14px}
.divider{
height:1px;background:var(--line);margin:0 0 15px}
.angle-label{
font-size:8px;letter-spacing:1px;color:#bda27e}
.angle-controls{
display:flex;gap:7px;margin:12px 0 14px}
.angle-btn{
height:35px;flex:1;border-radius:4px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.025);color:#88827a;font-size:17px}
.angle-btn:hover,.angle-btn.active{
border-color:rgba(209,174,132,.45);background:rgba(197,159,113,.1);color:#d8bc95}
.angle-side{
display:inline-block;transform:rotate(90deg)}
.angle-back{
display:inline-block;transform:rotate(180deg)}
.safety-note{
border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:11px 1px;display:flex;align-items:center;gap:9px;color:#858079;font-size:8px;line-height:1.45}
.safety-icon{
font-size:15px;color:#c8ab85}
.sound-row{
margin-top:auto;display:flex;align-items:center;gap:9px;padding-top:12px}
.sound-icon{
color:#d1b48b;font-size:16px}
.sound-row div{
display:flex;flex-direction:column;gap:3px}
.sound-row b{
font-size:9px;font-weight:500;color:#c7c0b7}
.sound-row small{
font-size:8px;color:#79746e}
.sound-toggle{
margin-left:auto;width:28px;height:15px;border-radius:20px;border:0;background:#4b4945;padding:2px;display:flex;align-items:center}
.sound-toggle i{
width:11px;height:11px;background:#bbb2a4;border-radius:50%;transition:.2s}
.sound-toggle.on{
background:#90785b;justify-content:flex-end}
.sound-toggle.on i{
background:#ead2b1}
.bottomline{
height:28px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(255,255,255,.055);font-size:7px;letter-spacing:1.15px;color:#67635e;flex-shrink:0}
.bottomline i{
font-style:normal;color:#90897e}
.bottomline b{
color:#b59a74;font-size:9px;margin-left:4px}

@media(max-width:1100px){
.app-shell{
padding:0 22px}
.workspace{
grid-template-columns:190px minmax(380px,1fr) 215px;gap:17px}
.look-swatch{
height:95px}
.tool-card{
height:54px}
.footer-tip{
display:none}
}
@media(max-width:820px){
html,body{
overflow:auto}
.app-shell{
height:auto;min-height:100dvh;padding:0 15px}
.topbar{
height:58px}
.workspace{
display:grid;grid-template-columns:minmax(0,1fr) 185px;grid-template-rows:minmax(390px,58vh) auto;gap:14px;padding:15px 0}
.stage-column{
grid-column:1;grid-row:1}
.left-rail{
grid-column:1;grid-row:2}
.tool-panel{
grid-column:2;grid-row:1 / span 2}
.left-rail{
display:grid;grid-template-columns:1fr 1fr;gap:9px;align-content:start}
.rail-heading{
grid-column:1 / span 2}
.look-card{
margin-top:0;grid-row:2 / span 2}
.coach-note{
margin-top:0}
.quality-card{
margin-top:0}
.rail-foot{
display:none}
.stage-footer{
height:56px}
.stage-topline>div:first-child{
gap:7px;flex-direction:column;align-items:flex-start}
.scene-status{
font-size:7px}
.bottomline{
margin-top:auto}
.tool-hint{
margin-bottom:10px}
.safety-note{
font-size:7px}
}
@media(max-width:570px){
.app-shell{
padding:0 10px}
.session-pill{
font-size:7px;letter-spacing:1px}
.quiet-btn{
font-size:10px}
.workspace{
display:flex;flex-direction:column;gap:10px;padding:10px 0}
.stage-column{
height:min(64vh,560px);min-height:405px}
.stage-topline{
height:29px}
.stage-topline>div:first-child{
display:flex;flex-direction:row;gap:7px}
.stage-sub{
font-size:7px}
.scene-status{
font-size:6px;letter-spacing:.5px}
.stage-footer{
height:53px}
.client-info{
min-width:120px}
.client-info span{
font-size:7px}
.avatar{
width:29px;height:29px}
.finish-btn{
padding:9px 10px;font-size:8px}
.tool-panel{
order:2}
.tools-header{
margin-top:1px}
.tool-list{
display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px}
.tool-card{
height:54px;padding:6px;gap:7px}
.tool-icon{
width:30px;height:30px}
.tool-icon svg{
width:24px;height:24px}
.tool-copy b{
font-size:8px}
.tool-copy small{
font-size:7px}
.tool-key{
font-size:7px;padding:1px 4px}
.tool-hint{
margin:7px 1px 8px;font-size:8px}
.divider{
margin:0 0 9px}
.view-heading{
margin-top:0}
.angle-controls{
margin:8px 0 10px}
.angle-btn{
height:30px}
.safety-note{
display:none}
.sound-row{
margin-top:8px;padding-top:9px;border-top:1px solid var(--line)}
.left-rail{
display:grid;grid-template-columns:1fr 1fr;gap:8px}
.rail-heading{
grid-column:1 / -1}
.look-card{
margin:0;padding:9px 10px;grid-row:2 / span 2}
.look-swatch{
height:85px}
.swatch-hair{
transform:scale(.8);transform-origin:top center;top:8px}
.look-title{
font-size:16px;margin-top:9px}
.look-subtitle{
font-size:8px}
.look-rule{
margin:10px 0 8px}
.goal-row{
font-size:9px}
.goal-caption{
font-size:7px}
.coach-note{
padding:9px 7px;gap:6px}
.coach-note p{
font-size:8px}
.coach-note b{
font-size:9px}
.quality-card{
padding-top:9px}
.quality-top{
font-size:7px}
.quality-card p{
font-size:8px}
.bottomline{
font-size:6px;letter-spacing:.5px}
.bottomline span:last-child{
display:none}
.headset-badge,.wind-status{
top:9px;padding:6px 7px;font-size:6px}
.headset-badge{
left:9px}
.wind-status{
right:9px}
.stage-bottom-left{
left:8px;bottom:8px}
.stage-bottom-right{
right:8px;bottom:8px}
.mouse-hint{
font-size:7px;padding:6px 7px}
.wind-btn{
font-size:8px;padding:5px 7px}
.stage{
border-radius:5px}
}

